/*
 * Manzil service worker.
 *
 * Hand-written rather than generated by next-pwa/workbox: the app runs Next 16
 * with the webpack builder and a strict CSP, and a ~120-line worker we fully
 * control is easier to reason about than a plugin's generated output — and adds
 * no build-time dependency that can break on the next Next.js major.
 *
 * Caching strategy, by request type:
 *
 *   Navigations   network-first, falling back to the cached page, then to the
 *                 offline page. Business profiles a user already opened stay
 *                 readable on a dropped connection, which is the point for a
 *                 local-discovery app on Uzbek mobile networks.
 *   Static assets stale-while-revalidate. Next fingerprints /_next/static, so a
 *                 cached hit is always correct for that URL.
 *   API calls     never cached. Serving a stale business listing, price, or
 *                 review as if it were live is worse than showing an error.
 */

const VERSION = "v2-anor";
const PAGE_CACHE = `manzil-pages-${VERSION}`;
const ASSET_CACHE = `manzil-assets-${VERSION}`;
const OFFLINE_URL = "/offline";

/** Cap the page cache so a heavy browsing session cannot fill the origin quota. */
const MAX_PAGES = 50;

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(PAGE_CACHE)
      .then((cache) => cache.add(OFFLINE_URL))
      // A failed precache must not block installation — the worker is still
      // useful for assets and for pages visited from here on.
      .catch(() => undefined)
      .then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((key) => key.startsWith("manzil-") && !key.endsWith(VERSION))
            .map((key) => caches.delete(key))
        )
      )
      .then(() => self.clients.claim())
  );
});

/** Trims the page cache to MAX_PAGES, oldest first. */
async function trimCache(cacheName, maxEntries) {
  const cache = await caches.open(cacheName);
  const keys = await cache.keys();

  if (keys.length <= maxEntries) return;

  for (const key of keys.slice(0, keys.length - maxEntries)) {
    await cache.delete(key);
  }
}

function isApiRequest(url) {
  return (
    url.pathname.startsWith("/api/") ||
    url.pathname.startsWith("/v1/") ||
    // The Sentry tunnel — replaying a cached error report would be nonsense.
    url.pathname.startsWith("/monitoring")
  );
}

function isStaticAsset(url) {
  return (
    url.pathname.startsWith("/_next/static/") ||
    url.pathname.startsWith("/icons/") ||
    /\.(?:css|js|woff2?|png|jpg|jpeg|svg|webp|avif|ico)$/.test(url.pathname)
  );
}

self.addEventListener("fetch", (event) => {
  const { request } = event;

  // Only GET is cacheable; a cached POST would silently drop a write.
  if (request.method !== "GET") return;

  const url = new URL(request.url);

  // Cross-origin (Clerk, Sentry, fonts) goes straight to the network — caching
  // another origin's auth or telemetry responses is never right.
  if (url.origin !== self.location.origin) return;

  if (isApiRequest(url)) return;

  if (request.mode === "navigate") {
    event.respondWith(
      (async () => {
        try {
          const response = await fetch(request);

          // Only cache real successes; an opaque/redirect/error response cached
          // as a page would resurface as a broken page offline.
          if (response.ok && response.type === "basic") {
            const cache = await caches.open(PAGE_CACHE);
            await cache.put(request, response.clone());
            void trimCache(PAGE_CACHE, MAX_PAGES);
          }

          return response;
        } catch {
          const cached = await caches.match(request);
          if (cached) return cached;

          const offline = await caches.match(OFFLINE_URL);
          if (offline) return offline;

          return new Response("Offline", {
            status: 503,
            headers: { "Content-Type": "text/plain; charset=utf-8" }
          });
        }
      })()
    );
    return;
  }

  if (isStaticAsset(url)) {
    event.respondWith(
      (async () => {
        const cache = await caches.open(ASSET_CACHE);
        const cached = await cache.match(request);

        const network = fetch(request)
          .then((response) => {
            if (response.ok) cache.put(request, response.clone());
            return response;
          })
          .catch(() => cached);

        // Stale-while-revalidate: serve the cached copy immediately when we
        // have one, and refresh it in the background.
        return cached ?? network;
      })()
    );
  }
});
